package com.srichaitanya.secureauth.api
import kotlinx.coroutines.flow.StateFlow
data class SecureAuthConfiguration(val baseUrl:String,val connectTimeoutSeconds:Long=10,val readTimeoutSeconds:Long=15,val allowOfflineBiometricUnlock:Boolean=false)
data class AuthUser(val id:String,val email:String,val displayName:String)
sealed interface AuthResult<out T>{ data class Success<T>(val value:T):AuthResult<T>; data class OtpRequired(val challengeId:String,val expiresInSeconds:Long):AuthResult<Nothing>; data object InvalidCredentials:AuthResult<Nothing>; data object InvalidOtp:AuthResult<Nothing>; data object AccountLocked:AuthResult<Nothing>; data object SessionExpired:AuthResult<Nothing>; data object Unauthorized:AuthResult<Nothing>; data object RateLimited:AuthResult<Nothing>; data class NetworkError(val retryable:Boolean):AuthResult<Nothing>; data class UnknownError(val requestId:String?):AuthResult<Nothing> }
sealed interface SessionState { data object Unauthenticated:SessionState; data object Authenticating:SessionState; data class OtpRequired(val challengeId:String):SessionState; data class Authenticated(val user:AuthUser?):SessionState; data object Refreshing:SessionState; data object Expired:SessionState; data object Locked:SessionState; data class Error(val result:AuthResult<Nothing>):SessionState }
sealed interface BiometricResult { data object Success:BiometricResult; data object Unavailable:BiometricResult; data object NotEnrolled:BiometricResult; data object LockedOut:BiometricResult; data object Cancelled:BiometricResult; data class Error(val message:String):BiometricResult }
interface SecureAuthClient { val sessionState:StateFlow<SessionState>; suspend fun login(email:String,password:String):AuthResult<Unit>; suspend fun register(email:String,password:String,displayName:String):AuthResult<Unit>; suspend fun verifyOtp(challengeId:String,otp:String):AuthResult<AuthUser?>; suspend fun refreshSession():AuthResult<Unit>; suspend fun logout(); suspend fun getCurrentUser():AuthUser?; fun isAuthenticated():Boolean }
